--[[
	airflow.rbxml -> reconstructed LocalScript
	Rebuilt from a Roblox UI dump (ScreenGui tree extracted from the .rbxml file).
	This recreates the visual interface only. Every button/toggle is wired to a
	no-op stub (left as nil / does nothing) as requested -- no actual feature
	logic (no exploit/cheat functionality) is implemented.

	Usage: put this in StarterPlayerScripts (or run it as a LocalScript in an
	executor). It builds the whole GUI tree under the LocalPlayer's PlayerGui.
]]

local Players = game:GetService("Players")
local player = Players.LocalPlayer
local playerGui = player:WaitForChild("PlayerGui")

-- The original dump was built on a 705x602 "design canvas" with font sizes
-- of only ~3-12px, squeezed down further by a UIScale of 0.525, which is why
-- everything rendered miniature. The hub's own UIScale is a child of the
-- main Frame, so it scales that Frame's Size AND all its descendants' pixel
-- offsets and TextSize together in one shot. We reuse that mechanism here:
-- compute the largest uniform scale that keeps the whole 705x602 canvas
-- inside a 410x320 box, so the entire hub -- buttons, paddings and text --
-- fits together with correct proportions and nothing overflows or clips.
local DESIGN_SIZE = Vector2.new(705, 602)
local TARGET_SIZE = Vector2.new(410, 320)
local UI_SCALE = math.min(TARGET_SIZE.X / DESIGN_SIZE.X, TARGET_SIZE.Y / DESIGN_SIZE.Y)

-- Safe property setter: some dumped properties are read-only, engine-internal,
-- or not valid for a given class. pcall keeps a bad property from breaking
-- the whole build.
local function setProp(inst, name, value)
	pcall(function()
		inst[name] = value
	end)
end

local function build(node, parent)
	local ok, inst = pcall(Instance.new, node.C)
	if not ok or not inst then
		return nil
	end

	if node.P then
		for name, value in pairs(node.P) do
			setProp(inst, name, value)
		end
	end

	if node.C == "UIScale" then
		setProp(inst, "Scale", UI_SCALE)
	end

	-- Interactive controls: wired up but intentionally left as no-ops (nil).
	-- No option here actually does anything -- fill in your own logic later.
	if node.C == "TextButton" then
		inst.MouseButton1Click:Connect(function()
			-- functionality intentionally left as nil / not implemented
		end)
	elseif node.C == "TextBox" then
		inst.FocusLost:Connect(function()
			-- functionality intentionally left as nil / not implemented
		end)
	end

	if node.K then
		for _, childNode in ipairs(node.K) do
			build(childNode, inst)
		end
	end

	inst.Parent = parent
	return inst
end

